import numpy as np

def feature(item, bins, capacity):
    """Minimum remaining resource after placing the item, normalised by the smaller capacity."""
    res = bins - item[None, :]
    bottleneck = np.minimum(res[:, 0], res[:, 1])
    denom = float(min(capacity[0], capacity[1]))
    if denom <= 0:
        return np.zeros(bins.shape[0])
    return bottleneck / denom

